def solve(a: str, b: str) -> int:
    # Use DP for Levenshtein distance with O(min(n,m)) space
    if len(a) < len(b):
        a, b = b, a  # ensure a is longer
    # now len(a) >= len(b)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                cost = 0
            else:
                cost = 1
            current[j] = min(
                previous[j] + 1,      # deletion
                current[j - 1] + 1,   # insertion
                previous[j - 1] + cost  # substitution
            )
        previous = current
    return previous[-1]

