    """Parse a CSV line into fields.
    Handles quoted fields where commas are literal and double quotes are escaped.
    Returns a list of field strings.
    """
    fields = []
    cur = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
