                # Do not add the quote itself
            else:
                cur.append(c)
        else:
            if c == '"':
                in_quotes = True
            elif c == ',':
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(c)
        i += 1
    # Append last field (covers empty input)
    fields.append(''.join(cur))
    return fields
