def solve(lst):
    """Flatten arbitrarily nested iterables containing integers.
    Any nested structure that is iterable (list, tuple, set, etc.) is traversed,
    but strings/bytes are treated as atomic and ignored. Booleans are not counted.
    """
    from collections.abc import Iterable
    result = []
    def helper(item):
        # strings/bytes are considered atomic, not iterable for our purpose
        if isinstance(item, (str, bytes, bytearray)):
            return
        if isinstance(item, int) and not isinstance(item, bool):
            result.append(item)
            return
        if isinstance(item, Iterable):
            for sub in item:
                helper(sub)
        # other types ignored
    helper(lst)
    return result

def solve(n: int, b: int) -> str:
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Digits 0-9 followed by a-z are used for values 10-35. Negative numbers
    include a leading '-'. Zero returns '0'.
    """
    if b < 2 or b > 36:
        raise ValueError('Base must be between 2 and 36')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

