def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value.
    Uses a sparse DP (dictionary) to handle large capacities efficiently.
    """
    dp = {0: 0}  # weight -> max value
    for w, v in zip(weights, values):
        if w > capacity:
            # item too heavy, skip
            continue
        # iterate over current dp items snapshot
        new_entries = {}
        for cur_w, cur_val in dp.items():
            new_w = cur_w + w
            if new_w > capacity:
                continue
            new_val = cur_val + v
            # if this weight not seen or we have a better value, store
            if new_w not in dp or new_val > dp[new_w]:
                # store in temporary to avoid modifying dict during iteration
                if new_w not in new_entries or new_val > new_entries[new_w]:
                    new_entries[new_w] = new_val
        # merge new entries
        dp.update(new_entries)
    # result is max value among all achievable weights
    return max(dp.values()) if dp else 0

