def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount using unlimited coins.
    If impossible, return -1.
    Dynamic programming O(amount * len(coins)).
    """
    # Edge case
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible number of coins
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

