def solve(s) -> bool:
    """Return True if brackets in s are balanced.
    Accepts any input; non‑string values are converted to their string representation.
    Only characters '()', '[]', '{}' are considered for balancing; all others are ignored.
    """
    # Ensure we have a string to iterate over
    if not isinstance(s, str):
        try:
            s = str(s)
        except Exception:
            return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    closing = set(pairs.keys())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

