def solve(s: str) -> bool:
    """Return True if s is a valid IPv4 address.
    Requirements:
    - Exactly four octets separated by '.'
    - Each octet contains only digits
    - No leading zeros unless the octet is exactly "0"
    - Integer value between 0 and 255 inclusive
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p or not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

