    from collections.abc import Iterable
    result = []
    def helper(item):
        # Exclude booleans
        if isinstance(item, bool):
            return
        if isinstance(item, int):
            result.append(item)
            return
        # Strings/bytes are iterable but should be ignored
        if isinstance(item, (str, bytes, bytearray)):
            return
        # If it's an iterable (list, tuple, set, etc.), recurse
        if isinstance(item, Iterable):
            for sub in item:
                helper(sub)
        # else ignore
    helper(lst)
    return result
