def solve(s: str) -> bool:
    """Return True if *s* is a valid IPv4 address.
    A valid address consists of exactly four decimal numbers separated by dots.
    Each number must be between 0 and 255 inclusive, contain no leading zeros
    except the number 0 itself, and contain only digits.
    """
    if not isinstance(s, str):
        return False
    # Strip whitespace but do not allow internal spaces
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
