def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n) time.
    """
    import bisect
    tails = []
    for x in nums:
        # Find insertion point for x in tails (the smallest tail >= x).
        # For strictly increasing, use bisect_left.
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

