def solve(s: str) -> bool:
    """Validate an IPv4 address.
    The address must consist of exactly four decimal numbers separated by dots.
    Each number must be between 0 and 255 inclusive, contain no leading zeros
    (unless the number itself is 0), and consist solely of digits.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Must be non‑empty and all digits
        if not part or not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

