def solve(data):
    """Run‑length encode *data*.
    Accepts a string or any iterable (list, tuple, bytes, etc.).
    Returns a list of [element, count] pairs in order.
    """
    # Convert non‑string iterables to a list; treat non‑iterables as a single element list.
    if isinstance(data, str):
        seq = list(data)
    else:
        try:
            # strings are also iterable, but we already handled them
            seq = list(data)
        except Exception:
            # fallback: treat the input as a single element
            seq = [data]
    if not seq:
        return []
    result = []
    prev = seq[0]
    count = 1
    for item in seq[1:]:
        if item == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = item
            count = 1
    result.append([prev, count])
    return result

